export type ParsedRegisterMerchantInstruction<
  TProgram extends string = typeof TALLY_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    authority: TAccountMetas[0];
    config: TAccountMetas[1];
    merchant: TAccountMetas[2];
    payout: TAccountMetas[3];
    skrMint: TAccountMetas[4];
    authoritySkr: TAccountMetas[5];
    bondVault: TAccountMetas[6];
    keyRecord: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
  };
  data: RegisterMerchantInstructionData;
};

export function parseRegisterMerchantInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRegisterMerchantInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      authority: getNextAccount(),
      config: getNextAccount(),
      merchant: getNextAccount(),
      payout: getNextAccount(),
      skrMint: getNextAccount(),
      authoritySkr: getNextAccount(),
      bondVault: getNextAccount(),
      keyRecord: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getRegisterMerchantInstructionDataDecoder().decode(instruction.data),
  };
}
